inline bool ContainsResource(std::string_view name)
{
    return Resources.find(name) != Resources.end();
}

inline const ResourceEntry* GetResource(std::string_view name)
{
    auto it = Resources.find(name);
    return (it != Resources.end()) ? &it->second : nullptr;
}

inline std::string GetResourceAsString(std::string_view name)
{
    auto* entry = GetResource(name);
    if (entry) {
        return std::string(reinterpret_cast<const char*>(entry->data), entry->size);
    }
    return {};
}

